import numpy as np
from v4 import (colmin, build, auction, build_par, untight_rows, augment,
                dense_check, merge_rows, unassign, bf_fix, auction_cached)


def solve_perm(C, th0=0.14, e0=0.03, fac=8.0, em=1e-7, th1=0.01, K=4):
    n = C.shape[0]
    v0 = colmin(C)
    x = -np.ones(n, np.int64)
    y = -np.ones(n, np.int64)
    ok = False
    for attempt in range(3):
        p = -v0
        ptr, idx, val = build(C, p, th0)
        eps = e0
        ok = True
        cj = -np.ones((n, K), np.int64)
        thr = np.full(n, -1e300)
        while True:
            x[:] = -1
            y[:] = -1
            if not auction_cached(n, ptr, idx, val, p, x, y, eps, 60 * n, cj, thr, K):
                ok = False
                break
            if eps <= em:
                break
            eps = max(eps / fac, em)
        if ok:
            break
        th0 *= 1.5
    fixed = False
    if ok:
        v = -p
        fixed = bf_fix(n, ptr, idx, val, v, x, 50 * n)
        if not fixed:
            v = -p
    else:
        v = v0.copy()
        x[:] = -1
        y[:] = -1
    if fixed:
        for i in range(n):
            pass
        y[x] = np.arange(n)
    else:
        ptr, idx, val = build_par(C, v, th1, np.maximum(x, 0) if ok else x)
        untight_rows(n, ptr, idx, val, v, x, y)
    while True:
        f = augment(n, ptr, idx, val, v, x, y)
        if f >= 0:
            bad = np.zeros(n, np.bool_)
            bad[f] = True
            ptr, idx, val = merge_rows(C, v, ptr, idx, val, bad, 1e300)
            continue
        bad = dense_check(C, -v, x, 1e-12)
        if not bad.any():
            return x
        ptr, idx, val = merge_rows(C, v, ptr, idx, val, bad, th1)
        unassign(x, y, bad)


class Solver:
    def __init__(self):
        C = np.random.rand(30, 30)
        solve_perm(C)

    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n, m = M.shape
        if n == m and n > 0 and np.all(a == a[0]) and np.all(b == a[0]):
            x = solve_perm(M)
            G = np.zeros((n, m))
            G[np.arange(n), x] = a[0]
            return {"transport_plan": G}
        import ot
        return {"transport_plan": ot.lp.emd(a, b, M, check_marginals=False)}

