import numpy as np, numba as nb

@nb.njit(cache=True)
def knn_edges(C, k):
    n, m = C.shape
    mask = np.zeros((n, m), np.bool_)
    # row knn
    bufv = np.empty(k); bufj = np.empty(k, np.int64)
    for i in range(n):
        cnt = 0
        for j in range(m):
            c = C[i, j]
            if cnt < k:
                p = cnt; cnt += 1
                while p > 0 and bufv[p-1] > c:
                    bufv[p] = bufv[p-1]; bufj[p] = bufj[p-1]; p -= 1
                bufv[p] = c; bufj[p] = j
            elif c < bufv[k-1]:
                p = k-1
                while p > 0 and bufv[p-1] > c:
                    bufv[p] = bufv[p-1]; bufj[p] = bufj[p-1]; p -= 1
                bufv[p] = c; bufj[p] = j
        for t in range(cnt):
            mask[i, bufj[t]] = True
    # column knn
    cv = np.empty((m, k)); ci = np.empty((m, k), np.int64); cc = np.zeros(m, np.int64)
    for i in range(n):
        for j in range(m):
            c = C[i, j]
            cnt = cc[j]
            if cnt < k:
                p = cnt; cc[j] = cnt + 1
            elif c < cv[j, k-1]:
                p = k-1
            else:
                continue
            while p > 0 and cv[j, p-1] > c:
                cv[j, p] = cv[j, p-1]; ci[j, p] = ci[j, p-1]; p -= 1
            cv[j, p] = c; ci[j, p] = i
    for j in range(m):
        for t in range(cc[j]):
            mask[ci[j, t], j] = True
    return mask

@nb.njit(cache=True)
def build_csr(C, mask):
    n, m = C.shape
    ptr = np.zeros(n + 1, np.int64)
    for i in range(n):
        s = 0
        for j in range(m):
            if mask[i, j]:
                s += 1
        ptr[i+1] = ptr[i] + s
    idx = np.empty(ptr[n], np.int64); val = np.empty(ptr[n])
    for i in range(n):
        p = ptr[i]
        for j in range(m):
            if mask[i, j]:
                idx[p] = j; val[p] = C[i, j]; p += 1
    return ptr, idx, val

@nb.njit(cache=True)
def lap_sparse(n, ptr, idx, val):
    INF = 1e300
    v = np.full(n, INF)
    x = -np.ones(n, np.int64); y = -np.ones(n, np.int64)
    am = -np.ones(n, np.int64)
    for i in range(n):
        for p in range(ptr[i], ptr[i+1]):
            j = idx[p]
            if val[p] < v[j]:
                v[j] = val[p]; am[j] = i
    for j in range(n):
        if v[j] >= INF:
            return x, v, False
        i = am[j]
        if x[i] < 0:
            x[i] = j; y[j] = i
    # Dijkstra augment
    d = np.full(n, INF); pred = np.empty(n, np.int64)
    done = np.zeros(n, np.bool_)
    touched = np.empty(n, np.int64); scanned = np.empty(n, np.int64)
    hk = np.empty(64 * n); hv = np.empty(64 * n, np.int64)
    for fr in range(n):
        if x[fr] >= 0:
            continue
        nt = 0; ns = 0; hs = 0
        for p in range(ptr[fr], ptr[fr+1]):
            j = idx[p]
