                    q = hs; hs += 1
                    while q > 0:
                        par = (q - 1) >> 1
                        if hk[par] <= h: break
                        hk[q] = hk[par]; hv[q] = hv[par]; q = par
                    hk[q] = h; hv[q] = j
        if endj < 0:
            return x, v, False
        for t in range(ns):
            j0 = scanned[t]
            v[j0] += d[j0] - mn
        for t in range(nt):
            j0 = touched[t]; d[j0] = INF; done[j0] = False
        j = endj
        while True:
            i = pred[j]; y[j] = i
            k = j; j = x[i]; x[i] = k
            if i == fr: break
    return x, v, True

@nb.njit(cache=True)
def check(C, x, v, mask, tol):
    n = C.shape[0]
    nbad = 0
    for i in range(n):
        u = C[i, x[i]] - v[x[i]]
        for j in range(n):
            if C[i, j] - u - v[j] < -tol:
                if not mask[i, j]:
                    mask[i, j] = True
                    nbad += 1
    return nbad

def solve_perm(C, k=8):
    n = C.shape[0]
    mask = knn_edges(C, k)
    for it in range(50):
        ptr, idx, val = build_csr(C, mask)
        x, v, ok = lap_sparse(n, ptr, idx, val)
        if not ok:
            k *= 2
            mask |= knn_edges(C, k)
            continue
        nb_ = check(C, x, v, mask, 1e-12)
        if nb_ == 0:
            return x
    return None
