import numpy as np, numba as nb

@nb.njit(cache=True)
def colmin(C):
    n = C.shape[0]
    v = C[0].copy(); am = np.zeros(n, np.int64)
    for i in range(1, n):
        for j in range(n):
            c = C[i, j]
            if c < v[j]:
                v[j] = c; am[j] = i
    return v, am

@nb.njit(cache=True)
def build(C, v, th):
    n = C.shape[0]
    ptr = np.empty(n + 1, np.int64); ptr[0] = 0
    cap = n * 48
    idx = np.empty(cap, np.int64); val = np.empty(cap)
    buf = np.empty(n)
    nnz = 0
    for i in range(n):
        m = 1e300
        for j in range(n):
            r = C[i, j] - v[j]
            buf[j] = r
            if r < m: m = r
        t = m + th
        if nnz + n > cap:
            cap = max(cap * 2, nnz + n)
            ni = np.empty(cap, np.int64); nv = np.empty(cap)
            ni[:nnz] = idx[:nnz]; nv[:nnz] = val[:nnz]
            idx = ni; val = nv
        for j in range(n):
            if buf[j] < t:
                idx[nnz] = j; val[nnz] = C[i, j]; nnz += 1
        ptr[i + 1] = nnz
    return ptr, idx, val

@nb.njit(cache=True)
def init_assign(n, am, x, y):
    for j in range(n):
        i = am[j]
        if x[i] < 0:
            x[i] = j; y[j] = i

@nb.njit(cache=True)
def arr(n, ptr, idx, val, v, x, y, maxit):
    INF = 1e300
