        for q in range(ptr[i], ptr[i+1]):
            j = idx[q]
            w = val[q] + p[j]
            if w < w2:
                if w < w1:
                    w2 = w1; w1 = w; j1 = j
                else:
                    w2 = w
        if w2 >= 1e299:
            w2 = w1 + 1.0
